<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import AppBreadcrumb from "@/components/AppBreadcrumb.vue";
import PageHeader from "@/components/PageHeader.vue";
import DataGrid, { type GridColumn } from "@/components/DataGrid.vue";
import { ApiError } from "@/services/http";
import { createAdminParameter, createParameterValue, listAdminParameters, listParameterValues, setAdminParameterState, setParameterValueState, updateAdminParameter, updateParameterValue, type Parameter, type ParameterValue } from "@/services/administracion";

type Tab = "parameters" | "values";
const tab = ref<Tab>("parameters"); const parameters = ref<Parameter[]>([]); const values = ref<ParameterValue[]>([]); const parameterPage = ref(1); const valuePage = ref(1); const parameterPagination = ref({ page: 1, pageSize: 10, total: 0, totalPages: 0 }); const valuePagination = ref({ page: 1, pageSize: 10, total: 0, totalPages: 0 }); const parameterSearch = ref(""); const valueSearch = ref(""); const valueParameterId = ref<number | undefined>(); const parameterState = ref<"all" | "active" | "inactive">("all"); const valueState = ref<"all" | "active" | "inactive">("all"); const loading = ref(false); const error = ref(""); const success = ref(""); const saving = ref(false); const parameterModal = ref(false); const valueModal = ref(false); const editingParameter = ref<Parameter | null>(null); const editingValue = ref<ParameterValue | null>(null);
const parameterForm = ref({ codigoParametro: "", nombreParametro: "", descripcionParametro: "", tipoDato: "STRING", valorPredeterminado: "", permiteModificacion: true });
const valueForm = ref({ idParametro: 0, valorParametro: "", codigoParametroValor: "", nombreParametroValor: "", descripcionParametroValor: "", tipoParametroValor: "STRING", fechaInicioVigencia: "", fechaFinVigencia: "" });
const parameterColumns: GridColumn[] = [{ key: "codigoParametro", label: "Código", width: "18%" }, { key: "nombreParametro", label: "Parámetro", width: "27%" }, { key: "tipoDato", label: "Tipo", width: "12%" }, { key: "valorPredeterminado", label: "Valor predeterminado", width: "25%" }, { key: "estadoParametro", label: "Estado", width: "10%" }];
const valueColumns: GridColumn[] = [{ key: "codigoParametroValor", label: "Código", width: "14%" }, { key: "nombreParametroValor", label: "Nombre", width: "18%" }, { key: "nombreParametro", label: "Parámetro", width: "20%" }, { key: "valorParametro", label: "Valor", width: "20%" }, { key: "tipoParametroValor", label: "Tipo", width: "11%" }, { key: "estadoParametroValor", label: "Estado", width: "10%" }];
const message = (cause: unknown) => cause instanceof ApiError ? cause.message : "Ocurrió un error inesperado";
const rowKey = (row: Record<string, unknown>) => String(row.idParametro ?? row.idParametroValor);
const dateValue = (value: string) => value ? new Date(`${value}T00:00:00`) : null;
const isBoolean = (type: string) => ["BOOLEAN", "BOOL", "BIT", "BOOLEANO", "LOGICO"].includes(type.trim().toUpperCase());
const inputType = (type: string) => ["INT", "INTEGER", "SMALLINT", "BIGINT", "ENTERO", "DECIMAL", "NUMERIC", "FLOAT", "NUMBER", "NUMERICO"].includes(type.trim().toUpperCase()) ? "number" : type.trim().toUpperCase() === "DATE" ? "date" : "text";
const parameterRows = computed(() => parameters.value as unknown as Record<string, unknown>[]); const valueRows = computed(() => values.value as unknown as Record<string, unknown>[]);
async function loadParameters() { loading.value = true; error.value = ""; try { const result = await listAdminParameters({ page: parameterPage.value, pageSize: 10, search: parameterSearch.value, estado: parameterState.value, sortBy: "codigoParametro", sortDirection: "asc" }); parameters.value = result.items; parameterPagination.value = result.pagination; } catch (cause) { error.value = message(cause); } finally { loading.value = false; } }
async function loadValues() { loading.value = true; error.value = ""; try { const result = await listParameterValues({ page: valuePage.value, pageSize: 10, search: valueSearch.value, idParametro: valueParameterId.value, estado: valueState.value, sortBy: "nombreParametroValor", sortDirection: "asc" }); values.value = result.items; valuePagination.value = result.pagination; } catch (cause) { error.value = message(cause); } finally { loading.value = false; } }
function loadActive() { return tab.value === "parameters" ? loadParameters() : loadValues(); }
function editParameter(item: Parameter | null) { editingParameter.value = item; parameterForm.value = { codigoParametro: item?.codigoParametro ?? "", nombreParametro: item?.nombreParametro ?? "", descripcionParametro: item?.descripcionParametro ?? "", tipoDato: item?.tipoDato ?? "STRING", valorPredeterminado: item?.valorPredeterminado ?? "", permiteModificacion: item?.permiteModificacion ?? true }; parameterModal.value = true; }
function editValue(item: ParameterValue | null) { editingValue.value = item; valueForm.value = { idParametro: item?.idParametro ?? parameters.value[0]?.idParametro ?? 0, valorParametro: item?.valorParametro ?? "", codigoParametroValor: item?.codigoParametroValor ?? "", nombreParametroValor: item?.nombreParametroValor ?? "", descripcionParametroValor: item?.descripcionParametroValor ?? "", tipoParametroValor: item?.tipoParametroValor ?? "STRING", fechaInicioVigencia: item?.fechaInicioVigencia?.slice(0, 10) ?? "", fechaFinVigencia: item?.fechaFinVigencia?.slice(0, 10) ?? "" }; valueModal.value = true; }
async function saveParameter() { saving.value = true; error.value = ""; try { const data = { ...parameterForm.value, descripcionParametro: parameterForm.value.descripcionParametro || null, valorPredeterminado: parameterForm.value.valorPredeterminado || null }; if (editingParameter.value) await updateAdminParameter(editingParameter.value.idParametro, data); else await createAdminParameter(data); parameterModal.value = false; success.value = "Parámetro guardado correctamente."; await loadParameters(); } catch (cause) { error.value = message(cause); } finally { saving.value = false; } }
async function saveValue() { saving.value = true; error.value = ""; try { const data = { ...valueForm.value, descripcionParametroValor: valueForm.value.descripcionParametroValor || null, fechaInicioVigencia: dateValue(valueForm.value.fechaInicioVigencia), fechaFinVigencia: dateValue(valueForm.value.fechaFinVigencia) }; if (editingValue.value) await updateParameterValue(editingValue.value.idParametroValor, data); else await createParameterValue(data); valueModal.value = false; success.value = "Valor de parámetro guardado correctamente."; await loadValues(); } catch (cause) { error.value = message(cause); } finally { saving.value = false; } }
async function toggleParameter(item: Parameter) { if (!window.confirm(`¿Confirma ${item.estadoParametro ? "desactivar" : "activar"} el parámetro ${item.codigoParametro}?`)) return; try { await setAdminParameterState(item.idParametro, !item.estadoParametro); await loadParameters(); } catch (cause) { error.value = message(cause); } }
async function toggleValue(item: ParameterValue) { if (!window.confirm(`¿Confirma ${item.estadoParametroValor ? "desactivar" : "activar"} este valor?`)) return; try { await setParameterValueState(item.idParametroValor, !item.estadoParametroValor); await loadValues(); } catch (cause) { error.value = message(cause); } }
function changePage(page: number) { if (tab.value === "parameters") { parameterPage.value = page; void loadParameters(); } else { valuePage.value = page; void loadValues(); } }
function selectTab(next: Tab) { tab.value = next; success.value = ""; error.value = ""; if (next === "parameters") void loadParameters(); else void loadValues(); }
onMounted(() => void loadParameters());
</script>

<template>
  <AppBreadcrumb :items="[{ label: 'Administración' }, { label: 'Configuración' }]" />
  <PageHeader eyebrow="Administración" title="Configuración" description="Administre parámetros institucionales y sus valores configurables." action-label="Actualizar" @action="loadActive" />
  <div v-if="success" class="bo-notice bo-notice-success">{{ success }}</div><div v-if="error" class="bo-state bo-state-error"><strong>{{ error }}</strong><button class="bo-btn" @click="loadActive">Reintentar</button></div>
  <nav class="configuration-tabs" aria-label="Configuración"><button :class="{ active: tab === 'parameters' }" @click="selectTab('parameters')">Parámetros</button><button :class="{ active: tab === 'values' }" @click="selectTab('values')">Valores de parámetros</button></nav>
  <section v-if="tab === 'parameters'" class="bo-card"><form class="bo-toolbar" @submit.prevent="parameterPage = 1; loadParameters()"><input v-model="parameterSearch" placeholder="Buscar código, nombre o descripción..." aria-label="Buscar parámetros" /><select v-model="parameterState"><option value="all">Todos los estados</option><option value="active">Activos</option><option value="inactive">Inactivos</option></select><button class="bo-btn bo-btn-primary">Buscar</button><button type="button" class="bo-btn" @click="editParameter(null)">Nuevo parámetro</button></form><DataGrid :columns="parameterColumns" :rows="parameterRows" :row-key="rowKey" :pagination="parameterPagination" :loading="loading" :error="error" empty-text="No hay parámetros para mostrar." @page="changePage"><template #cell-valorPredeterminado="{ row }">{{ row.valorPredeterminado ?? "Sin valor" }}</template><template #cell-estadoParametro="{ row }"><span class="status-badge" :class="{ 'status-badge--inactive': !row.estadoParametro }">{{ row.estadoParametro ? "Activo" : "Inactivo" }}</span></template><template #actions="{ row }"><button class="bo-action" @click="editParameter(row as unknown as Parameter)">Editar</button><button class="bo-action" :class="{ danger: row.estadoParametro }" @click="toggleParameter(row as unknown as Parameter)">{{ row.estadoParametro ? "Desactivar" : "Activar" }}</button><button class="bo-action" @click="selectTab('values'); valueParameterId = Number(row.idParametro); valuePage = 1; loadValues()">Valores</button></template></DataGrid></section>
  <section v-else class="bo-card"><form class="bo-toolbar" @submit.prevent="valuePage = 1; loadValues()"><input v-model="valueSearch" placeholder="Buscar valor, código o parámetro..." aria-label="Buscar valores" /><select v-model="valueParameterId"><option :value="undefined">Todos los parámetros</option><option v-for="item in parameters" :key="item.idParametro" :value="item.idParametro">{{ item.nombreParametro }} ({{ item.codigoParametro }})</option></select><select v-model="valueState"><option value="all">Todos los estados</option><option value="active">Activos</option><option value="inactive">Inactivos</option></select><button class="bo-btn bo-btn-primary">Buscar</button><button type="button" class="bo-btn" @click="editValue(null)">Nuevo valor</button></form><DataGrid :columns="valueColumns" :rows="valueRows" :row-key="rowKey" :pagination="valuePagination" :loading="loading" :error="error" empty-text="No hay valores para mostrar." @page="changePage"><template #cell-valorParametro="{ row }">{{ row.valorParametro || "Sin configurar" }}</template><template #cell-estadoParametroValor="{ row }"><span class="status-badge" :class="{ 'status-badge--inactive': !row.estadoParametroValor }">{{ row.estadoParametroValor ? "Activo" : "Inactivo" }}</span></template><template #actions="{ row }"><button class="bo-action" @click="editValue(row as unknown as ParameterValue)">Editar</button><button class="bo-action" :class="{ danger: row.estadoParametroValor }" @click="toggleValue(row as unknown as ParameterValue)">{{ row.estadoParametroValor ? "Desactivar" : "Activar" }}</button></template></DataGrid></section>
  <div v-if="parameterModal" class="bo-modal-backdrop" @click.self="parameterModal = false"><section class="bo-modal"><header><div><span class="bo-eyebrow">Configuración</span><h2>{{ editingParameter ? "Editar parámetro" : "Nuevo parámetro" }}</h2></div><button class="bo-close" @click="parameterModal = false">×</button></header><form class="bo-form" @submit.prevent="saveParameter"><label>Código *<input v-model="parameterForm.codigoParametro" :disabled="Boolean(editingParameter)" required /></label><label>Nombre *<input v-model="parameterForm.nombreParametro" required /></label><label>Descripción<textarea v-model="parameterForm.descripcionParametro" rows="2" /></label><label>Tipo de dato *<input v-model="parameterForm.tipoDato" required /></label><label>Valor predeterminado<textarea v-model="parameterForm.valorPredeterminado" rows="2" /></label><label class="bo-check-label"><input v-model="parameterForm.permiteModificacion" type="checkbox" /> Permite modificación</label><footer class="form-actions"><button type="button" class="bo-btn" @click="parameterModal = false">Cancelar</button><button class="bo-btn bo-btn-primary" :disabled="saving">Guardar</button></footer></form></section></div>
  <div v-if="valueModal" class="bo-modal-backdrop" @click.self="valueModal = false"><section class="bo-modal"><header><div><span class="bo-eyebrow">Configuración</span><h2>{{ editingValue ? "Editar valor" : "Nuevo valor" }}</h2></div><button class="bo-close" @click="valueModal = false">×</button></header><form class="bo-form" @submit.prevent="saveValue"><label>Parámetro *<select v-model.number="valueForm.idParametro" :disabled="Boolean(editingValue)" required><option :value="0" disabled>Seleccione...</option><option v-for="item in parameters" :key="item.idParametro" :value="item.idParametro">{{ item.nombreParametro }} ({{ item.codigoParametro }})</option></select></label><label>Código del valor *<input v-model="valueForm.codigoParametroValor" required /></label><label>Nombre del valor *<input v-model="valueForm.nombreParametroValor" required /></label><label>Valor *<textarea v-model="valueForm.valorParametro" rows="2" required /></label><label>Tipo *<input v-model="valueForm.tipoParametroValor" required /></label><label>Descripción<textarea v-model="valueForm.descripcionParametroValor" rows="2" /></label><label>Inicio de vigencia<input v-model="valueForm.fechaInicioVigencia" type="date" /></label><label>Fin de vigencia<input v-model="valueForm.fechaFinVigencia" type="date" /></label><footer class="form-actions"><button type="button" class="bo-btn" @click="valueModal = false">Cancelar</button><button class="bo-btn bo-btn-primary" :disabled="saving || !valueForm.idParametro">Guardar</button></footer></form></section></div>
</template>

<style scoped>
.configuration-tabs { display: flex; gap: 4px; margin-bottom: 12px; border-bottom: 1px solid var(--bo-line); }.configuration-tabs button { padding: 11px 15px; border: 0; border-bottom: 2px solid transparent; color: var(--bo-muted); background: transparent; cursor: pointer; font-size: 12px; font-weight: 700; }.configuration-tabs button.active { color: var(--bo-blue); border-bottom-color: var(--bo-blue); }
.bo-modal { width: min(720px, calc(100vw - 32px)); max-width: 100%; max-height: calc(100vh - 32px); overflow-x: hidden; overflow-y: auto; }
.bo-form { min-width: 0; }.bo-form label { min-width: 0; }.bo-form input, .bo-form select, .bo-form textarea { width: 100%; max-width: 100%; min-width: 0; box-sizing: border-box; }.bo-form textarea { resize: vertical; }.bo-check-label { display: flex !important; align-items: center; gap: 8px; }.bo-check-label input { width: auto; flex: 0 0 auto; }.form-actions { position: sticky; bottom: -18px; z-index: 1; margin: 0 -18px -18px; padding: 14px 18px; background: #fff; }
@media (max-width: 600px) { .bo-modal { width: calc(100vw - 20px); max-height: calc(100vh - 20px); padding: 16px; }.form-actions { bottom: -16px; margin: 0 -16px -16px; padding: 12px 16px; } }
</style>
